// @material 1
// @control {"name":"tint","label":"Metal tint","type":"vec3","default":[0.79,0.8,0.81]}
// @control {"name":"brush","label":"Brush strength","type":"float","default":0.055,"min":0,"max":0.4}
// @control {"name":"grain","label":"Grain","type":"float","default":0.03,"min":0,"max":0.2}
// @control {"name":"sheen","label":"Highlight","type":"float","default":0.16,"min":0,"max":1}
// @control {"name":"spread","label":"Highlight width","type":"float","default":0.32,"min":0.05,"max":1}
// Brushed metal card surface. Fine horizontal grooves at two scales, an
// anisotropic highlight that runs across the grooves and slides with tilt (as
// real brushed metal does), and a little grain. First stage: it ignores its input.

// Noise read at whole texels and blended along x: long, smooth grooves.
float groove(vec2 px, float stretch, float rowHeight, float seed) {
  float row = floor(px.y / rowHeight);
  float x = px.x / stretch + seed * 97.0;
  float i = floor(x);
  float f = fract(x);
  float a = texture(r_noise, (vec2(i, row) + 0.5) / 1024.0);
  float b = texture(r_noise, (vec2(i + 1.0, row) + 0.5) / 1024.0);
  return mix(a, b, f * f * (3.0 - 2.0 * f)) - 0.5;
}

vec4 material(vec2 uv) {
  vec2 px = uv * sl_resolution;
  // Scale grooves with the card so they read the same at any resolution.
  float s = sl_resolution.x / 740.0;
  float grooves =
    groove(px, 150.0 * s, max(1.0, 1.0 * s), 0.0) * 0.6 +
    groove(px, 320.0 * s, max(1.0, 1.6 * s), 3.0) * 0.4;
  float grain = texture(r_noise, px / 1024.0 + 0.5) - 0.5;

  // Anisotropic highlight: a soft vertical band that the grooves break up.
  vec2 t = sl_tilt;
  float c = 0.5 + t.x * 0.55 + (uv.y - 0.5) * 0.18;
  float band = exp(-pow((uv.x - c) / p_spread, 2.0));
  float echo = exp(-pow((uv.x - c + 0.42) / (p_spread * 1.6), 2.0)) * 0.35;
  float highlight = (band + echo) * (0.85 + grooves * 0.8);

  // Light falls off slightly toward the bottom and the edges.
  float falloff = 1.0 - 0.07 * uv.y - 0.05 * pow(abs(uv.x - 0.5) * 2.0, 2.0);

  vec3 color = p_tint * falloff * (1.0 + grooves * p_brush)
    + highlight * p_sheen * vec3(1.0, 1.0, 1.01)
    + grain * p_grain;
  return vec4(clamp(color, 0.0, 1.0), 1.0);
}

