// @material 1
// @control {"name":"height","label":"Height map","type":"samplerFloat"}
// @control {"name":"depth","label":"Depth","type":"float","default":3.5,"min":0,"max":20}
// @control {"name":"strength","label":"Shading","type":"float","default":0.6,"min":0,"max":2}
// @control {"name":"shine","label":"Specular","type":"float","default":0.2,"min":0,"max":1}
// Light a height map over the previous stage. 0.5 is flat, brighter is raised,
// darker is pressed in. Lighting direction follows tilt.
vec4 material(vec2 uv) {
  vec4 color = texture(r_input, uv);
  vec2 texel = 1.0 / sl_resolution;
  float h = texture(sp_height, uv);
  float hl = texture(sp_height, uv - vec2(texel.x, 0.0));
  float hr = texture(sp_height, uv + vec2(texel.x, 0.0));
  float hu = texture(sp_height, uv - vec2(0.0, texel.y));
  float hd = texture(sp_height, uv + vec2(0.0, texel.y));
  vec2 slope = vec2(hr - hl, hd - hu) * p_depth * 0.5 * sl_resolution.y / 100.0;
  vec3 n = normalize(vec3(-slope, 1.0));

  vec3 light = normalize(vec3(-0.45 - sl_tilt.x * 0.9, -0.7 - sl_tilt.y * 0.9, 0.75));
  float flat_ = light.z;
  float diffuse = dot(n, light) - flat_;
  vec3 view = vec3(0.0, 0.0, 1.0);
  float spec = pow(max(dot(reflect(-light, n), view), 0.0), 28.0);
  float edge = clamp(length(slope) * 1.5, 0.0, 1.0);
  float occlusion = min(h - 0.5, 0.0) * 0.35;

  color.rgb *= 1.0 + diffuse * p_strength + occlusion;
  color.rgb += spec * p_shine * edge;
  return color;
}

