// @material 1
// @control {"name":"mask","label":"Foil mask (blurred)","type":"samplerFloat"}
// @control {"name":"region","label":"Foil box (uv)","type":"vec4","default":[0,0,1,1]}
// @control {"name":"warm","label":"Warm tint","type":"vec3","default":[1,0.62,0.06]}
// @control {"name":"tint","label":"Tint amount","type":"float","default":0.9,"min":0,"max":1}
// @control {"name":"bevel","label":"Bevel","type":"float","default":0.8,"min":0,"max":30}
// @control {"name":"cutout","label":"Transparent outside","type":"float","default":0,"min":0,"max":1}
// Chrome foil with a warm tint, inside a soft mask. The mask's own gradient is
// used as a bevel so the edge reads as a rounded, stamped foil.
// `region` is the foil's box in this output's uv (x, y, width, height), so the
// tint lands in the same place whether the output is the card or just the flame.
// cutout = 1 makes everything outside the mask transparent, so an object
// carrying this material shows the card itself rather than a copy of it.
vec4 material(vec2 uv) {
  vec4 color = texture(r_input, uv);
  color.a *= 1.0 - p_cutout;
  vec2 texel = 1.0 / sl_resolution;
  float m = texture(sp_mask, uv);
  float cover = smoothstep(0.42, 0.58, m);
  if (cover <= 0.0) return color;

  float ml = texture(sp_mask, uv - vec2(texel.x * 2.0, 0.0));
  float mr = texture(sp_mask, uv + vec2(texel.x * 2.0, 0.0));
  float mu = texture(sp_mask, uv - vec2(0.0, texel.y * 2.0));
  float md = texture(sp_mask, uv + vec2(0.0, texel.y * 2.0));
  vec2 slope = vec2(mr - ml, md - mu) * p_bevel;
  vec3 n = normalize(vec3(-slope, 1.0));

  vec2 local = (uv - p_region.xy) / max(p_region.zw, vec2(1e-4));
  vec2 t = sl_tilt * 0.6;

  // Procedural studio environment: soft bands read as polished chrome.
  vec3 r = reflect(vec3(0.0, 0.0, -1.0), n);
  float sweep = local.x * 1.1 + local.y * 1.4 + r.x * 0.9 + r.y * 0.6 + t.x - t.y * 0.5;
  float bands = 0.5 + 0.5 * sin(sweep * 4.5 + 0.6);
  float chrome = mix(0.66, 1.02, pow(bands, 1.4));
  chrome += 0.12 * exp(-pow((sweep - 1.3) * 3.0, 2.0));

  // Warm tint enters from the top-right of the foil and shifts with tilt.
  float w = local.x * 0.95 + (1.0 - local.y) * 0.5 + 0.08 * sin(local.y * 7.0 + t.x * 3.0) - t.x * 0.25;
  float warmBand = smoothstep(0.95, 1.3, w);
  vec3 foil = mix(vec3(chrome), vec3(chrome) * p_warm * 1.1, warmBand * p_tint);

  color.rgb = mix(color.rgb, foil, cover);
  color.a = mix(color.a, 1.0, cover);
  return color;
}

