// @material 1
// @control {"name":"density","label":"Dots across","type":"float","default":28,"min":6,"max":80}
// @control {"name":"center","label":"Field centre","type":"vec2","default":[0.92,0.42]}
// @control {"name":"radius","label":"Field radius","type":"float","default":1.15,"min":0.1,"max":2}
// @control {"name":"strength","label":"Dot brightness","type":"float","default":0.42,"min":0,"max":0.6}
// @control {"name":"tiltSize","label":"Size on tilt","type":"float","default":0.6,"min":0,"max":1}
// Halftone dot field over the previous stage, fading away from a centre point.
// Tilt changes the dots' size, not their brightness: a wave of growing and
// shrinking dots travels across the card as it tilts.
vec4 material(vec2 uv) {
  vec4 color = texture(r_input, uv);
  float aspect = sl_resolution.x / max(sl_resolution.y, 1.0);
  vec2 q = vec2(uv.x * aspect, uv.y) * p_density;
  float row = floor(q.y);
  q.x += mod(row, 2.0) * 0.5;
  vec2 cell = fract(q) - 0.5;
  vec2 cellUv = (floor(q) + 0.5 - vec2(mod(row, 2.0) * 0.5, 0.0)) / p_density;
  cellUv.x /= aspect;

  vec2 toCenter = (cellUv - p_center) * vec2(aspect, 1.0);
  float field = 1.0 - smoothstep(0.0, p_radius * aspect * 0.5, length(toCenter));

  // Each dot's size swings with tilt; neighbours are out of phase, so the
  // swing reads as a wave moving across the field. Flat card = base size.
  float phase = dot(cellUv * vec2(aspect, 1.0), vec2(5.0, 2.5));
  float swing = sin(phase + sl_tilt.x * 4.0 + sl_tilt.y * 2.5) - sin(phase);
  float size = clamp(1.0 + p_tiltSize * swing, 0.0, 2.0);
  float r = min(0.42 * pow(field, 0.8) * size, 0.49);

  float aa = 1.5 * p_density / sl_resolution.x * aspect;
  float dotMask = 1.0 - smoothstep(r - aa, r + aa, length(cell));
  color.rgb = mix(color.rgb, vec3(1.0), dotMask * p_strength);
  return color;
}

