// Designed SVG print layers are prepared once by the template's caller.
vec3 overlayBlend(vec3 base, vec3 top) {
  return mix(2.0 * base * top, 1.0 - 2.0 * (1.0 - base) * (1.0 - top), step(0.5, base));
