// @material 1
// @control {"name":"tint","label":"Metal tint","type":"vec3","default":[0.8,0.805,0.81]}
// @control {"name":"grain","label":"Grain","type":"float","default":0.068,"min":0,"max":0.25}
// @control {"name":"sheen","label":"Sheen","type":"float","default":0.165,"min":0,"max":0.6}
// @control {"name":"softness","label":"Sheen size","type":"float","default":0.688,"min":0.1,"max":1.5}
// Satin (bead-blasted) metal: a fine even grain and a broad, soft sheen that
// drifts with tilt. First stage: it ignores its input.
vec4 material(vec2 uv) {
  vec2 px = uv * sl_resolution;
  float s = max(1.0, sl_resolution.x / 740.0);
  float fine = texture(r_noise, px / 1024.0) - 0.5;
  float coarse = texture(r_noise, floor(px / (2.0 * s)) / 1024.0 + 0.37) - 0.5;
  float grain = fine * 0.55 + coarse * 0.45;

  float aspect = sl_resolution.x / max(sl_resolution.y, 1.0);
  vec2 c = vec2(0.5 + sl_tilt.x * 0.45, 0.35 + sl_tilt.y * 0.35);
  vec2 d = (uv - c) * vec2(aspect, 1.0);
  float glow = exp(-dot(d, d) / (p_softness * p_softness));

  vec3 color = p_tint * (0.96 - 0.06 * uv.y) + glow * p_sheen + grain * p_grain;
  return vec4(clamp(color, 0.0, 1.0), 1.0);
}

