  float diffuse = dot(n, light) - light.z;

  vec3 r = reflect(vec3(0.0, 0.0, -1.0), n);
  float sweep = uv.x * 1.2 + uv.y * 0.8 + r.x + r.y * 0.6 + sl_tilt.x * 0.6 - sl_tilt.y * 0.3;
  float chrome = mix(0.5, 1.0, pow(0.5 + 0.5 * sin(sweep * 5.0), 1.4));
